package com.nigson.experience.careers;
import java.util.*;import org.springframework.transaction.support.TransactionSynchronizationManager;import software.amazon.awssdk.core.SdkBytes;import software.amazon.awssdk.services.kms.KmsClient;import software.amazon.awssdk.services.kms.model.DecryptRequest;
/** Career-only wrapped key loading. Raw local key material is accepted only for local/test. */
public final class CareerKeys {
 private CareerKeys(){}
 public static CareerSecrets load(KmsClient kms,String env,int hashVersion,String revision,String arn,String wrappedHash,String wrappedCipher,String localHash,String localCipher,String previous){
  if(!Set.of("local","test","dev","qa","stage","prod").contains(env)||hashVersion<1||revision==null||!revision.matches("[A-Za-z0-9_-]{1,40}")||previous==null||previous.length()>25000)throw policy();var json=tools.jackson.databind.json.JsonMapper.builder(tools.jackson.core.json.JsonFactory.builder().enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build()).enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();var prior=json.readTree(previous);if(prior==null||!prior.isObject()||prior.size()>2)throw policy();var keys=new HashMap<String,byte[]>();byte[] hash;
  if(!localHash.isBlank()||!localCipher.isBlank()){if(!Set.of("local","test").contains(env)||!arn.isBlank()||!wrappedHash.isBlank()||!wrappedCipher.isBlank()||!prior.isEmpty())throw policy();try{hash=Base64.getDecoder().decode(localHash);keys.put(revision,Base64.getDecoder().decode(localCipher));return new CareerSecrets(hashVersion,hash,revision,keys);}catch(IllegalArgumentException invalid){throw policy();}}
  if(kms==null||!arn.matches("arn:aws(?:-us-gov|-cn)?:kms:[a-z0-9-]+:[0-9]{12}:key/[a-f0-9-]{36}"))throw policy();hash=unwrap(kms,arn,wrappedHash,"email-index",Integer.toString(hashVersion));keys.put(revision,unwrap(kms,arn,wrappedCipher,"email-cipher",revision));for(var e:prior.properties()){if(!e.getKey().matches("[A-Za-z0-9_-]{1,40}")||keys.containsKey(e.getKey())||!e.getValue().isString())throw policy();keys.put(e.getKey(),unwrap(kms,arn,e.getValue().asString(),"email-cipher",e.getKey()));}return new CareerSecrets(hashVersion,hash,revision,keys);
 }
 private static byte[] unwrap(KmsClient kms,String arn,String wrapped,String kind,String revision){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("CAREER_KEY_HTTP_OUTSIDE_TRANSACTION_REQUIRED");if(wrapped==null||wrapped.isBlank()||wrapped.length()>12000)throw policy();try{var out=kms.decrypt(DecryptRequest.builder().keyId(arn).ciphertextBlob(SdkBytes.fromByteArray(Base64.getDecoder().decode(wrapped))).encryptionContext(Map.of("purpose","nigson-experience-careers","kind",kind,"revision",revision)).build());if(!arn.equals(out.keyId())||out.plaintext().asByteArray().length!=32)throw policy();return out.plaintext().asByteArray();}catch(Exception e){throw new IllegalStateException("CAREER_KEY_UNAVAILABLE");}}
 private static IllegalArgumentException policy(){return new IllegalArgumentException("CAREER_KEY_POLICY_REQUIRED");}
}
